<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';try{$pdo=db();$k=$pdo->query("SELECT COUNT(*) total_skus,COALESCE(SUM(v.available_qty),0) total_units,COALESCE(SUM(v.available_qty<i.reorder_level AND v.available_qty>0),0) low_stock,COALESCE(SUM(v.available_qty=0),0) out_stock FROM items i LEFT JOIN v_item_availability v ON v.item_id=i.id WHERE i.is_active=1")->fetch();$k['open_alerts']=(int)$pdo->query("SELECT COUNT(*) FROM low_stock_alerts WHERE status IN ('draft','sent')")->fetchColumn();$k['expiring_30']=(int)$pdo->query('SELECT COUNT(DISTINCT b.id) FROM batches b JOIN stock_levels sl ON sl.batch_id=b.id WHERE sl.quantity>0 AND b.expiration_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 30 DAY)')->fetchColumn();$items=$pdo->query('SELECT i.id,i.sku,i.name,i.unit,i.reorder_level,i.reorder_qty,i.unit_cost,s.name supplier,COALESCE(v.available_qty,0) available_qty FROM items i LEFT JOIN suppliers s ON s.id=i.preferred_supplier_id LEFT JOIN v_item_availability v ON v.item_id=i.id WHERE i.is_active=1 ORDER BY (v.available_qty=0) DESC,(v.available_qty<i.reorder_level) DESC,i.name LIMIT 100')->fetchAll();$warehouses=$pdo->query('SELECT w.name,COALESCE(SUM(CASE WHEN b.expiration_date>=CURDATE() THEN sl.quantity ELSE 0 END),0) units FROM warehouses w LEFT JOIN stock_levels sl ON sl.warehouse_id=w.id LEFT JOIN batches b ON b.id=sl.batch_id WHERE w.is_active=1 GROUP BY w.id ORDER BY w.name')->fetchAll();json_response(true,['kpis'=>$k,'items'=>$items,'warehouses'=>$warehouses]);}catch(Throwable $e){api_error($e);}
